export function Navbar() {
  const { user, logout } = useAuth();
  const { count } = useCart();
  const { balance } = useBalance();
  const location = useLocation();

  const [theme, setTheme] = useState(() => {
    return document.documentElement.getAttribute('data-theme') || 'light';
  });

  const toggleTheme = () => {
    const next = theme === 'dark' ? 'light' : 'dark';
    setTheme(next);
    document.documentElement.setAttribute('data-theme', next);
    localStorage.setItem('dinobox_theme', next);
  };

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
  }, [theme]);

  const formatCLP = (n) =>
    new Intl.NumberFormat('es-CL', { style: 'currency', currency: 'CLP', maximumFractionDigits: 0 }).format(n);

  const links = [
    { to: '/', label: 'Home' },
    { to: '/products', label: 'Products' },
    ...(user ? [
      { to: '/cart', label: 'Cart' },
      { to: '/orders', label: 'Orders' },
      { to: '/account', label: 'Account' },
      { to: '/balance', label: 'Balance' }
    ] : [])
  ];

  return (
    <nav className="sticky top-0 z-50 glass" aria-label="Main navigation">
      <div className="max-w-7xl mx-auto px-6 py-3 flex items-center justify-between gap-3">

        <Link to="/" className="flex items-center gap-2 group shrink-0">
          <motion.div
            whileHover={{ rotate: 360 }}
            transition={{ duration: 0.6 }}
            className="w-8 h-8 rounded-md bg-gradient-to-br from-dino-accent to-dino-mint flex items-center justify-center font-bold text-white text-sm"
            style={{ boxShadow: 'inset 0 1px 0 rgba(255,255,255,.5), 0 1px 2px rgba(0,0,0,.2)' }}
          >
            D
          </motion.div>
          <span className="font-display font-bold text-lg" style={{ color: 'var(--heading)' }}>
            DinoBox <span className="new-badge ml-1">beta</span>
          </span>
        </Link>

        <div className="flex items-center gap-1 flex-wrap justify-center">
          {links.map(link => (
            <Link
              key={link.to}
              to={link.to}
              className="relative px-3 py-1.5 text-xs font-bold uppercase tracking-wider"
              style={{
                color: location.pathname === link.to ? 'var(--link)' : 'var(--text-muted)'
              }}
            >
              {link.label}
              {link.label === 'Cart' && count > 0 && (
                <motion.span
                  initial={{ scale: 0 }}
                  animate={{ scale: 1 }}
                  className="absolute -top-1 -right-1 w-4 h-4 rounded-full text-[10px] flex items-center justify-center font-bold text-white"
                  style={{
                    background: 'linear-gradient(to bottom, #f0ad4e 0%, #d9534f 100%)',
                    border: '1px solid #a02a25',
                    boxShadow: 'inset 0 1px 0 rgba(255,255,255,.4)'
                  }}
                >
                  {count}
                </motion.span>
              )}
              {location.pathname === link.to && (
                <motion.div
                  layoutId="nav-indicator"
                  className="absolute bottom-0 left-1 right-1 h-0.5"
                  style={{ background: 'var(--link)' }}
                />
              )}
            </Link>
          ))}
        </div>

        <div className="flex items-center gap-2 shrink-0">
          {user ? (
            <>
              <div className="text-right hidden sm:block">
                <p className="text-[10px] uppercase tracking-wider" style={{ color: 'var(--text-muted)' }}>
                  Balance
                </p>
                <p className="font-mono font-bold text-xs" style={{ color: 'var(--link)' }}>
                  {formatCLP(balance)}
                </p>
              </div>
              <div className="text-right hidden md:block">
                <p className="text-[10px] uppercase tracking-wider" style={{ color: 'var(--text-muted)' }}>
                  Hi,
                </p>
                <p className="font-bold text-xs">{user.username}</p>
              </div>
              <button
                onClick={logout}
                className="text-xs font-bold"
                style={{ color: 'var(--text-muted)' }}
              >
                Logout
              </button>
            </>
          ) : (
            <Link to="/login" className="btn-primary !px-4 !py-1.5 text-xs">
              Sign In
            </Link>
          )}

          {/* THEME TOGGLE — bulletproof: inline styles + CSS class + visible label */}
          <button
            type="button"
            onClick={toggleTheme}
            className="theme-toggle"
            aria-label={`Switch to ${theme === 'dark' ? 'light' : 'dark'} mode`}
            title={`Switch to ${theme === 'dark' ? 'light' : 'dark'} mode`}
            style={{
              display: 'inline-flex',
              alignItems: 'center',
              justifyContent: 'center',
              gap: 6,
              height: 28,
              padding: '0 10px',
              borderRadius: 999,
              border: '1px solid var(--input-border, #a4b8cc)',
              background: theme === 'dark'
                ? 'linear-gradient(to bottom, #3a4553 0%, #232b36 50%, #151b23 100%)'
                : 'linear-gradient(to bottom, #ffffff 0%, #e2ecf6 50%, #cdd9e6 100%)',
              color: theme === 'dark' ? '#ffd166' : '#1e2a38',
              fontFamily: 'Tahoma, Verdana, Arial, sans-serif',
              fontSize: 11,
              fontWeight: 'bold',
              cursor: 'pointer',
              boxShadow: 'inset 0 1px 0 rgba(255,255,255,.5), 0 1px 2px rgba(0,0,0,.15)',
              flexShrink: 0
            }}
          >
            {theme === 'dark' ? <SunIcon /> : <MoonIcon />}
            <span className="hidden sm:inline">
              {theme === 'dark' ? 'Light' : 'Dark'}
            </span>
          </button>
        </div>
      </div>
    </nav>
  );
}

import { motion, AnimatePresence } from 'framer-motion';
import { usePackageSimulation } from '../hooks/usePackageSimulation';
import { useBalance } from '../context/BalanceContext';
import { useState, useEffect, useRef } from 'react';
import api from '../services/api';

const STATE_CONFIG = {
  PENDING:          { label: 'Pending',          color: '#f59e0b', icon: '⏳' },
  EN_ROUTE:         { label: 'En Route',         color: '#60a5fa', icon: '🚚' },
  WE_HAVE_NO_IDEA:  { label: 'We Have No Idea',  color: '#a78bfa', icon: '🌀' },
  ARRIVED:          { label: 'Arrived',          color: '#34d399', icon: '✓' },
  LOST:             { label: 'Lost',             color: '#ef4444', icon: '✗' }
};

export function OrderTracker({ order, onComplete }) {
  const simulationId = order.id;
  const trackingCode = order.orderId;
  const { state, nextChangeIn } = usePackageSimulation(simulationId, trackingCode, order.currentState);
  const { addFunds } = useBalance();

  const [refunding, setRefunding] = useState(false);
  const [refunded, setRefunded] = useState(order.isRefunded || false);
  const [showDetails, setShowDetails] = useState(false);
  const [orderDetails, setOrderDetails] = useState(null);

  // Keep latest onComplete without resetting the effect on every parent render
  const onCompleteRef = useRef(onComplete);
  useEffect(() => {
    onCompleteRef.current = onComplete;
  }, [onComplete]);

  // Fire onComplete ONCE when the order reaches a "done" state
  const hasFired = useRef(false);
  useEffect(() => {
    const isDone = state === 'ARRIVED' || (state === 'LOST' && refunded);
    if (!isDone || hasFired.current) return;

    hasFired.current = true;
    // Show the final state for 3s, then let the parent fly it to the receipts icon
    const timer = setTimeout(() => onCompleteRef.current?.(), 3000);
    return () => clearTimeout(timer);
  }, [state, refunded]);

  // Pull saved line-items from localStorage
  useEffect(() => {
    if (!trackingCode) return;
    const saved = localStorage.getItem(`dinobox_order_${trackingCode}`);
    if (saved) setOrderDetails(JSON.parse(saved));
  }, [trackingCode]);

  const config = STATE_CONFIG[state] || STATE_CONFIG.PENDING;
  const isTerminal = state === 'ARRIVED' || state === 'LOST';
  const totalPaid = orderDetails?.totalPaid || order.totalPaid || 0;

  const handleRefund = async () => {
    setRefunding(true);
    // 2-4 second simulated processing
    const delay = 2 + Math.random() * 2;
    await new Promise(r => setTimeout(r, delay * 1000));

    addFunds(totalPaid);

    try {
      await api.put(`/orders/${order.id}/refund`);
    } catch (e) {
      console.error("Refund failed", e);
    }

    setRefunded(true);
    setRefunding(false);
  };

  const formatCLP = (n) =>
    new Intl.NumberFormat('es-CL', { style: 'currency', currency: 'CLP', maximumFractionDigits: 0 }).format(n);

  return (
    <motion.div layout className="glass rounded-2xl p-5 relative overflow-hidden" aria-live="polite">
      <div className="flex items-start justify-between mb-4">
        <div>
          <p className="text-xs text-dino-muted font-mono">Order #{trackingCode}</p>
          <p className="text-sm text-dino-text mt-1">{order.location}</p>
        </div>
        <div className="text-right">
          <p className="text-xs text-dino-muted">Total</p>
          <p className="font-bold gradient-text">{formatCLP(totalPaid)}</p>
        </div>
      </div>

      <div className="flex items-center gap-3 mb-3">
        <motion.div
          key={state}
          initial={{ scale: 0, rotate: -180 }}
          animate={{ scale: 1, rotate: 0 }}
          className="w-12 h-12 rounded-full flex items-center justify-center text-2xl"
          style={{ background: `${config.color}20`, border: `2px solid ${config.color}` }}
        >
          {config.icon}
        </motion.div>
        <div>
          <p className="font-semibold" style={{ color: config.color }}>{config.label}</p>
          {!isTerminal && nextChangeIn !== null && (
            <p className="text-xs text-dino-muted font-mono">
              Next update in {nextChangeIn}s
            </p>
          )}
        </div>
      </div>

      <div className="h-1.5 bg-dino-bg rounded-full overflow-hidden mb-4">
        <motion.div
          className="h-full"
          style={{ background: config.color }}
          initial={{ width: '0%' }}
          animate={{
            width: state === 'PENDING' ? '20%' :
                   state === 'EN_ROUTE' ? '50%' :
                   state === 'WE_HAVE_NO_IDEA' ? '70%' : '100%'
          }}
          transition={{ duration: 0.8 }}
        />
      </div>

      {orderDetails?.items && orderDetails.items.length > 0 && (
        <div className="border-t border-dino-accent/10 pt-3">
          <button
            onClick={() => setShowDetails(!showDetails)}
            className="text-xs text-dino-glow hover:text-dino-accent transition-colors flex items-center gap-1"
          >
            {showDetails ? 'Hide' : 'View'} purchased items ({orderDetails.items.length})
            <span className={`transform transition-transform ${showDetails ? 'rotate-180' : ''}`}>▼</span>
          </button>

          <AnimatePresence>
            {showDetails && (
              <motion.div
                initial={{ height: 0, opacity: 0 }}
                animate={{ height: 'auto', opacity: 1 }}
                exit={{ height: 0, opacity: 0 }}
                className="overflow-hidden mt-2 space-y-2"
              >
                {orderDetails.items.map((item, idx) => (
                  <div key={idx} className="flex justify-between text-sm bg-dino-bg/50 p-2 rounded-lg">
                    <span className="text-dino-text">{item.qty}x {item.name}</span>
                    <span className="font-mono text-dino-muted">{formatCLP(item.price * item.qty)}</span>
                  </div>
                ))}
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      )}

      <AnimatePresence>
        {state === 'LOST' && !refunded && totalPaid > 0 && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            className="mt-4"
          >
            <button
              onClick={handleRefund}
              disabled={refunding}
              className="w-full btn-primary !py-2 text-sm"
            >
              {refunding ? 'Processing refund...' : 'Request Refund'}
            </button>
          </motion.div>
        )}
        {refunded && (
          <motion.p
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            className="text-center text-dino-mint text-sm font-medium mt-4"
          >
            ✓ Refunded {formatCLP(totalPaid)} to your balance
          </motion.p>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

