  const totalSpent = orders
    .filter(o => o.status === 'ACTIVE')
    .reduce((sum, o) => sum + (o.totalAmount || 0), 0);
  const totalRefunded = orders
    .filter(o => o.status === 'REFUNDED')
    .reduce((sum, o) => sum + (o.totalAmount || 0), 0);

